-- Seed for contractor_tickers and contractor_ticker_prefixes.
-- Same rows as scripts/data/contractor-tickers.json, which
-- scripts/seed-contractor-tickers.mjs upserts without a migration. To correct
-- a mapping: fix the row in the table (or the JSON and re-seed), then
--   update contractor_recipients set tickered_at = null; select contractor_resolve_tickers();
--
-- source = 'exchange': the recipient's normalised name equals a listed
-- company's normalised name (NYSE / Nasdaq / AMEX listings, multi-word names
-- only). source = 'manual': hand-checked subsidiaries, DBAs and known-private
-- contractors. is_public = false rows carry no ticker on purpose.

